import numpy as np
from scipy import stats

MAX_DRIVERS = 5

def design(feats):
    # Check for strong correlations (|r| >= 0.6) among features
    corr_matrix = np.corrcoef(feats.x.T)
    high_corr_pairs = []
    for i in range(len(feats.ids)):
        for j in range(i+1, len(feats.ids)):
            if abs(corr_matrix[i,j]) >= 0.6:
                high_corr_pairs.append((feats.ids[i], feats.ids[j]))

    # If no strong correlations, no mechanism
    if not high_corr_pairs:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Group correlated features into modules
    feature_groups = []
    used_features = set()

    for a, b in high_corr_pairs:
        if a in used_features or b in used_features:
            # Try to merge with existing group
            merged = False
            for group in feature_groups:
                if a in group or b in group:
                    group.add(a)
                    group.add(b)
                    merged = True
                    break
            if not merged:
                feature_groups.append({a, b})
        else:
            feature_groups.append({a, b})

        used_features.add(a)
        used_features.add(b)

    # If no groups formed, no mechanism
    if not feature_groups:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Use the largest group as our module
    largest_group = max(feature_groups, key=len)
    module_features = list(largest_group)

    # Calculate weighted loading score using mean values
    loadings = {}
    for fid in module_features:
        idx = feats.column(fid)
        # Weight by effect size difference
        mean_y1 = np.mean(feats.x[feats.y==1, idx])
        mean_y0 = np.mean(feats.x[feats.y==0, idx])
        loadings[fid] = mean_y1 - mean_y0

    # Select drivers by effect size (max 4 to stay under limit)
    effect_sizes = [(fid, abs(loadings[fid])) for fid in module_features]
    effect_sizes.sort(key=lambda x: x[1], reverse=True)
    drivers = tuple(fid for fid, _ in effect_sizes[:min(4, len(effect_sizes))])

    # Include all module features in columns
    columns = tuple(module_features)

    # No interaction terms
    products = ()

    return Design(drivers=drivers, columns=columns, products=products, loadings=loadings)
